BEGIN;
CREATE TABLE IF NOT EXISTS app_users(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), issuer text NOT NULL, subject text NOT NULL, display_name text NOT NULL, UNIQUE(tenant_id,issuer,subject), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS memberships(
 tenant_id uuid NOT NULL REFERENCES tenants(id), user_id uuid NOT NULL,
 role text NOT NULL CHECK(role IN('admin','hr','manager','employee','reviewer')),employee_external_id text,
 active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,user_id), UNIQUE(tenant_id,employee_external_id), FOREIGN KEY(tenant_id,user_id) REFERENCES app_users(tenant_id,id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,user_id uuid NOT NULL,expires_at timestamptz NOT NULL,FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS manager_assignments(tenant_id uuid NOT NULL,manager_user_id uuid NOT NULL,employee_external_id text NOT NULL,PRIMARY KEY(tenant_id,manager_user_id,employee_external_id),FOREIGN KEY(tenant_id,manager_user_id) REFERENCES memberships(tenant_id,user_id) ON DELETE CASCADE);
ALTER TABLE inventory_tasks ADD COLUMN IF NOT EXISTS revision integer NOT NULL DEFAULT 1;
ALTER TABLE inventory_tasks ADD COLUMN IF NOT EXISTS review_state text NOT NULL DEFAULT 'pending' CHECK(review_state IN('pending','accepted','rejected'));
CREATE UNIQUE INDEX IF NOT EXISTS inventory_tenant_id_unique ON inventory_tasks(tenant_id,id);
CREATE TABLE IF NOT EXISTS task_versions(tenant_id uuid NOT NULL,task_id uuid NOT NULL,revision integer NOT NULL,description text NOT NULL,role_name text NOT NULL,skill_tags text[] NOT NULL,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,task_id,revision),FOREIGN KEY(tenant_id,task_id) REFERENCES inventory_tasks(tenant_id,id) ON DELETE CASCADE);
INSERT INTO task_versions(tenant_id,task_id,revision,description,role_name,skill_tags) SELECT tenant_id,id,revision,task_description,role_name,skill_tags FROM inventory_tasks ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS task_reviews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,task_id uuid NOT NULL,revision integer NOT NULL,reviewer_id uuid NOT NULL,decision text NOT NULL CHECK(decision IN('accepted','rejected')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,task_id,revision) REFERENCES task_versions(tenant_id,task_id,revision) ON DELETE CASCADE,UNIQUE(tenant_id,task_id,revision));
CREATE TABLE IF NOT EXISTS role_map_reviews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,employee_external_id text NOT NULL,role_name text NOT NULL,snapshot text NOT NULL,accepted boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,employee_external_id,role_name,snapshot));
CREATE TABLE IF NOT EXISTS assessments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,task_id uuid NOT NULL,task_revision integer NOT NULL,category text NOT NULL CHECK(category IN('assist','partially_automate','human_led','uncertain')),confidence text NOT NULL CHECK(confidence IN('low','medium','high','uncalibrated')),rationale text NOT NULL,model text NOT NULL,rubric_version text NOT NULL,prompt_version text NOT NULL,status text NOT NULL DEFAULT 'suggested' CHECK(status IN('suggested','reviewed','stale')),reviewer_id uuid,review_reason text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,task_id,task_revision,rubric_version),FOREIGN KEY(tenant_id,task_id,task_revision) REFERENCES task_versions(tenant_id,task_id,revision) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS skill_catalogue(id text PRIMARY KEY,name text NOT NULL,resource_title text NOT NULL,resource_url text NOT NULL,exercise text NOT NULL,rubric text NOT NULL,version integer NOT NULL DEFAULT 1);
INSERT INTO skill_catalogue(id,name,resource_title,resource_url,exercise,rubric) VALUES
('typescript','TypeScript','TypeScript handbook','https://www.typescriptlang.org/docs/handbook/intro.html','Implement a typed validation function with boundary cases.','Types are explicit, invalid input is handled, and boundary tests pass.'),
('testing','Testing','Node.js testing documentation','https://nodejs.org/api/test.html','Write an integration test covering a success and failure path.','Test demonstrates observable behaviour and catches a deliberate defect.'),
('sql','SQL','PostgreSQL tutorial','https://www.postgresql.org/docs/current/tutorial.html','Write a query and explain its correctness on a sample dataset.','Query returns expected rows and handles missing values.'),
('communication','Communication','Google technical writing','https://developers.google.com/tech-writing','Explain a technical decision to a non-specialist reader.','Explanation states the decision, trade-off and next action clearly.'),
('documentation','Documentation','Diátaxis documentation framework','https://diataxis.fr/','Create a how-to guide with prerequisites and a verifiable result.','A reviewer can follow the guide and reproduce the stated result.'),
('data-quality','Data quality','PostgreSQL constraints','https://www.postgresql.org/docs/current/ddl-constraints.html','Define checks for a dataset and report anomalies using synthetic data.','Checks identify invalid records and explain remediation.'),
('problem-solving','Problem solving','Google SRE troubleshooting','https://sre.google/sre-book/effective-troubleshooting/','Investigate a synthetic incident and document hypotheses and evidence.','Investigation tests competing hypotheses and supports its conclusion.'),
('accessibility','Accessibility','W3C accessibility tutorials','https://www.w3.org/WAI/tutorials/','Review a form and correct its keyboard and labelling issues.','Controls have labels, visible focus and an operable keyboard flow.'),
('security','Security','OWASP cheat sheets','https://cheatsheetseries.owasp.org/','Threat-model a small API and implement one mitigation.','Threat, trust boundary and tested mitigation are explicit.') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS role_skill_targets(tenant_id uuid NOT NULL REFERENCES tenants(id),role_name text NOT NULL,skill_id text NOT NULL REFERENCES skill_catalogue(id),target_level integer NOT NULL CHECK(target_level BETWEEN 1 AND 4),PRIMARY KEY(tenant_id,role_name,skill_id));
CREATE TABLE IF NOT EXISTS employee_skills(tenant_id uuid NOT NULL REFERENCES tenants(id),employee_external_id text NOT NULL,skill_id text NOT NULL REFERENCES skill_catalogue(id),self_level integer CHECK(self_level BETWEEN 0 AND 4),verified_level integer CHECK(verified_level BETWEEN 0 AND 4),verified_at timestamptz,PRIMARY KEY(tenant_id,employee_external_id,skill_id));
CREATE TABLE IF NOT EXISTS learning_plans(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),employee_external_id text NOT NULL,revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','completed','cancelled')),weekly_minutes integer NOT NULL CHECK(weekly_minutes BETWEEN 30 AND 600),snapshot jsonb NOT NULL,start_date date,end_date date,stale boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS single_open_plan ON learning_plans(tenant_id,employee_external_id) WHERE status IN('draft','active');
CREATE TABLE IF NOT EXISTS plan_revisions(tenant_id uuid NOT NULL,plan_id uuid NOT NULL,revision integer NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,plan_id,revision),FOREIGN KEY(tenant_id,plan_id) REFERENCES learning_plans(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS plan_activities(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,plan_id uuid NOT NULL,plan_revision integer NOT NULL,skill_id text NOT NULL REFERENCES skill_catalogue(id),day integer NOT NULL CHECK(day BETWEEN 1 AND 30),minutes integer NOT NULL CHECK(minutes>0),title text NOT NULL,exercise text NOT NULL,rubric text NOT NULL,resource_url text NOT NULL,target_level integer NOT NULL CHECK(target_level BETWEEN 1 AND 4),completed_at timestamptz,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,plan_id,plan_revision) REFERENCES plan_revisions(tenant_id,plan_id,revision) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS plan_approvals(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,plan_id uuid NOT NULL,revision integer NOT NULL,reviewer_id uuid NOT NULL,approved_at timestamptz NOT NULL DEFAULT now(),start_date date NOT NULL,UNIQUE(tenant_id,plan_id,revision),FOREIGN KEY(tenant_id,plan_id,revision) REFERENCES plan_revisions(tenant_id,plan_id,revision) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cohort_members(tenant_id uuid NOT NULL,employee_external_id text NOT NULL,plan_id uuid NOT NULL,enrolled_at timestamptz NOT NULL DEFAULT now(),withdrawn_at timestamptz,PRIMARY KEY(tenant_id,employee_external_id),FOREIGN KEY(tenant_id,plan_id) REFERENCES learning_plans(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS evidence(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,activity_id uuid NOT NULL,employee_external_id text NOT NULL,reviewer_id uuid NOT NULL,object_key text NOT NULL,filename text NOT NULL,mime text NOT NULL,bytes integer NOT NULL CHECK(bytes>0 AND bytes<=5242880),status text NOT NULL DEFAULT 'quarantined' CHECK(status IN('quarantined','clean','infected','verified','rejected')),review_reason text,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,activity_id) REFERENCES plan_activities(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),kind text NOT NULL CHECK(kind IN('assess','scan','delete')),idempotency_key text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','retry_wait','succeeded','failed','cancelled')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,last_error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE INDEX IF NOT EXISTS jobs_due_idx ON jobs(tenant_id,status,available_at);
CREATE TABLE IF NOT EXISTS outbox_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),kind text NOT NULL,idempotency_key text NOT NULL,payload jsonb NOT NULL,delivered_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS token_budgets(tenant_id uuid NOT NULL REFERENCES tenants(id),day date NOT NULL DEFAULT CURRENT_DATE,used_tokens integer NOT NULL DEFAULT 0 CHECK(used_tokens>=0),PRIMARY KEY(tenant_id,day));
CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),actor_id uuid,action text NOT NULL,resource_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS privacy_requests(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),employee_external_id text NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','completed','blocked')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant_policies(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),legal_hold boolean NOT NULL DEFAULT false,evidence_retention_days integer CHECK(evidence_retention_days BETWEEN 1 AND 3650),policy_approved_at timestamptz);
INSERT INTO tenant_policies(tenant_id) SELECT id FROM tenants ON CONFLICT DO NOTHING;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['app_users','memberships','sessions','manager_assignments','inventory_tasks','import_batches','task_versions','task_reviews','role_map_reviews','assessments','role_skill_targets','employee_skills','learning_plans','plan_revisions','plan_activities','plan_approvals','cohort_members','evidence','jobs','outbox_events','token_budgets','audit_events','privacy_requests','tenant_policies'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename=t AND policyname='tenant_isolation') THEN
   EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t);
  END IF;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION immutable_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Snapshots and audit events are immutable'; END $$;
DROP TRIGGER IF EXISTS task_snapshot_immutable ON task_versions;
CREATE TRIGGER task_snapshot_immutable BEFORE UPDATE ON task_versions FOR EACH ROW EXECUTE FUNCTION immutable_snapshot();
DROP TRIGGER IF EXISTS plan_snapshot_immutable ON plan_revisions;
CREATE TRIGGER plan_snapshot_immutable BEFORE UPDATE ON plan_revisions FOR EACH ROW EXECUTE FUNCTION immutable_snapshot();
DROP TRIGGER IF EXISTS audit_immutable ON audit_events;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_snapshot();
INSERT INTO schema_migrations(version) VALUES('002-workflows') ON CONFLICT DO NOTHING;
COMMIT;
